package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.media3.datasource.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import java.util.*;import java.io.*;import java.security.*;import java.lang.reflect.*;import java.time.Duration;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=android.app.Application.class)
public class LibraryPlayer163Test {
 Context c;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.getSharedPreferences("profile",0).edit().putString("id","123").commit();Provider p=new Provider("VolnaSyntheticKeyStore",1.0,"test only"){};p.put("KeyStore.AndroidKeyStore",WarmWriterTest.MemoryStore.class.getName());Security.insertProviderAt(p,1);Session.put(c,"OAuth SYNTHETIC_163_TOKEN_12345","SYNTHETIC_163_CLIENT_12345");}
 @After public void done(){PlaybackService.instance=null;Security.removeProvider("VolnaSyntheticKeyStore");}
 Library.Track track(String id,long duration)throws Exception{Library.Track t=new Library.Track("sc:"+id,"Синее небо","Ёлка",duration,true);t.remote=new JSONObject().put("id",id).put("full_duration",duration).put("downloadable",false);return t;}
 OfflineStore store(Library.Track source,long measured){ScApi api=new ScApi(c){public Library.Track freshTrack(Library.Track t){return source;}public Stream playable(Library.Track t,boolean offline){return new Stream("https://cf-media.sndcdn.com/fixture-163.mp3",false,"",false,source.duration);}};return new OfflineStore(c){protected ScApi api(){return api;}protected DataSource.Factory networkSource(){return ()->new ByteArrayDataSource(new byte[8192]);}protected long measuredCache(DataSource.Factory f,String u){return measured;}};}
 OfflineStore.Progress progress=new OfflineStore.Progress(){public boolean cancelled(){return false;}public void update(int p){}};
 @Test public void searchMatchesArtistCaseAndYo()throws Exception{assertTrue(LibrarySearch.matches(track("1",180000),"ЕЛКА небо"));assertFalse(LibrarySearch.matches(track("1",180000),"небо rock"));}
 @Test public void clearingSearchRestoresAllTracks()throws Exception{List<Library.Track> all=Arrays.asList(track("1",180000),track("2",180000));assertEquals(0,LibrarySearch.filter(all,"unmatched").size());assertEquals(2,LibrarySearch.filter(all,"").size());assertEquals(2,all.size());}
 @Test public void scansAllPlaylistsAndDeduplicatesSongs()throws Exception{int[] count={0};List<Library.Track> result=LibrarySearch.all(new LibrarySearch.Source(){public List<JSONObject> playlists()throws Exception{return Arrays.asList(new JSONObject().put("id","a"),new JSONObject().put("id","b"),new JSONObject().put("id","a"));}public List<Library.Track> tracks(JSONObject p)throws Exception{count[0]++;return Arrays.asList(track("same",180000),track(p.optString("id"),180000));}public void check(){}},"небо");assertEquals(2,count[0]);assertEquals(3,result.size());}
 @Test public void searchCancellationIsNotPartialSuccess()throws Exception{try{LibrarySearch.all(new LibrarySearch.Source(){public List<JSONObject> playlists()throws Exception{return Arrays.asList(new JSONObject().put("id","a"));}public List<Library.Track> tracks(JSONObject p){return Collections.emptyList();}public void check()throws Exception{throw new InterruptedIOException();}},"q");fail();}catch(InterruptedIOException expected){}}
 @Test public void equalClockMeansEqualBars(){for(int k=0;k<5;k++)assertEquals(WaveClock.bar(100000,k),WaveClock.bar(100000,k),0);assertNotEquals(WaveClock.bar(100000,2),WaveClock.bar(100500,2),.0001);}
 @Test public void rejectsMeasuredPreviewEvenIfApiClaimsFull()throws Exception{Library.Track t=track("1",180000);try{store(t,30000).save(t,progress);fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("превью"));}assertTrue(new OfflineStore(c).list().isEmpty());}
 @Test public void unknownMeasuredDurationIsNotReady()throws Exception{Library.Track t=track("1",180000);try{store(t,0).save(t,progress);fail();}catch(IOException expected){}assertTrue(new OfflineStore(c).list().isEmpty());}
 @Test public void failedReplacementKeepsOldCopy()throws Exception{Library.Track old=track("1",30000);Library.Track copy=store(old,30000).save(old,progress);Library.Track full=track("1",180000);try{store(full,30000).save(full,progress);fail();}catch(IOException expected){}assertNotNull(new OfflineStore(c).find(copy.uri));assertEquals(1,new OfflineStore(c).list().size());}
 @Test public void fullReplacementCommitsThenRemovesOldCopy()throws Exception{Library.Track old=track("1",30000);Library.Track copy=store(old,30000).save(old,progress);Library.Track full=track("1",180000);Library.Track replacement=store(full,180000).save(full,progress);assertEquals(replacement.uri,new OfflineStore(c).find(copy.uri).uri);assertNotNull(new OfflineStore(c).find(replacement.uri));assertEquals(180000,replacement.duration);assertEquals(1,new OfflineStore(c).list().size());}
 @Test public void shortLegacyCopyGetsDurableRepairPlan()throws Exception{Library.Track old=track("1",30000);Library.Track copy=store(old,30000).save(old,progress);new OfflineStore(c).observedDuration(copy.uri,30000,180000);try(SyncDb db=new SyncDb(c)){assertEquals(1,db.workPlans("123").size());assertEquals("track:1",db.workPlans("123").get(0).optString("id"));assertTrue(db.workPlans("123").get(0).optBoolean("active"));assertEquals(180000,db.tracks("123","track:1").get(0).duration);}}
 @Test public void exclusionsAreScopedToAccountAndCanBeReenabled(){OfflineStore store=new OfflineStore(c);store.exclude("1");assertTrue(store.excluded("1"));c.getSharedPreferences("profile",0).edit().putString("id","456").commit();assertFalse(store.excluded("1"));c.getSharedPreferences("profile",0).edit().putString("id","123").commit();store.allow("1");assertFalse(store.excluded("1"));}
 @Test public void deletingSourceMarksAllPlansRemoved()throws Exception{try(SyncDb db=new SyncDb(c)){for(String p:new String[]{"likes","other"}){db.ensure("123",p,p,"own");db.snapshot("123",p,Arrays.asList(track("1",180000)));db.sourceReady("123","1");}db.sourceRemoved("123","1");for(String p:new String[]{"likes","other"}){assertEquals(0,db.totals("123",p)[1]);assertEquals(0,db.totals("123",p)[3]);}}}
 @Test public void previewRepairPolicyLeavesNearFullTracksAlone()throws Exception{assertFalse(OfflineQuality.shortCopy(179000,180000));assertTrue(OfflineQuality.shortCopy(30000,180000));}
 @Test public void pausedServiceRemainsAfterOldGracePeriod()throws Exception{ServiceController<PlaybackService> ctrl=Robolectric.buildService(PlaybackService.class).create();PlaybackService service=ctrl.get();service.pause();Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(31));assertFalse(Shadows.shadowOf(service).isStoppedBySelf());ctrl.destroy();}
 @Test public void activePlaybackIntentSurvivesTaskRemoval()throws Exception{ServiceController<PlaybackService> ctrl=Robolectric.buildService(PlaybackService.class).create();Field f=PlaybackService.class.getDeclaredField("intent");f.setAccessible(true);((FocusIntent)f.get(ctrl.get())).play();ctrl.get().onTaskRemoved(new Intent());assertFalse(Shadows.shadowOf(ctrl.get()).isStoppedBySelf());ctrl.destroy();}
 @Test public void pausedTaskRemovalKeepsService()throws Exception{ServiceController<PlaybackService> ctrl=Robolectric.buildService(PlaybackService.class).create();ctrl.get().onTaskRemoved(new Intent());assertFalse(Shadows.shadowOf(ctrl.get()).isStoppedBySelf());ctrl.destroy();}
 @Test public void excludedSourceCannotBeCommitted()throws Exception{Library.Track t=track("1",180000);new OfflineStore(c).exclude("1");try{store(t,180000).save(t,progress);fail();}catch(InterruptedIOException expected){}assertTrue(new OfflineStore(c).list().isEmpty());}
 @Test public void exclusionDuringTransferPreventsFinalCommit()throws Exception{Library.Track t=track("1",180000);ScApi fake=new ScApi(c){public Library.Track freshTrack(Library.Track old){return t;}public Stream playable(Library.Track old,boolean offline){return new Stream("https://cf-media.sndcdn.com/race163.mp3",false,"",false,180000);}};OfflineStore saver=new OfflineStore(c){protected ScApi api(){return fake;}protected DataSource.Factory networkSource(){return ()->new ByteArrayDataSource(new byte[1024]);}protected long measuredCache(DataSource.Factory f,String u){new OfflineStore(c).exclude("1");return 180000;}};try{saver.save(t,progress);fail();}catch(InterruptedIOException expected){}assertTrue(new OfflineStore(c).list().isEmpty());}
 @Test public void taskRemovalSavesCurrentAndNextTrackWithoutStoppingMusic()throws Exception{Library library=new Library(c);library.upsert(track("1",180000));library.upsert(track("2",180000));library.save();ServiceController<PlaybackService> ctrl=Robolectric.buildService(PlaybackService.class).create();PlaybackService service=ctrl.get();Field q=PlaybackService.class.getDeclaredField("queue");q.setAccessible(true);q.set(service,new ArrayList<>(Arrays.asList("sc:1","sc:2")));service.current="sc:1";Field f=PlaybackService.class.getDeclaredField("intent");f.setAccessible(true);((FocusIntent)f.get(service)).play();service.onTaskRemoved(new Intent());PlaybackCheckpoint.Snapshot saved=PlaybackCheckpoint.read(c);assertNotNull(saved);assertTrue(saved.wanted);assertEquals(Arrays.asList("sc:1","sc:2"),saved.queue);assertFalse(Shadows.shadowOf(service).isStoppedBySelf());ctrl.destroy();}

 @Test public void queuedOldOfflineIdentifierOpensReplacement()throws Exception{Library.Track old=track("1",30000);Library.Track copy=store(old,30000).save(old,progress);Library.Track full=track("1",180000);Library.Track replacement=store(full,180000).save(full,progress);try(OfflineStore.Open open=new OfflineStore(c).open(copy.uri)){assertFalse(open.drm);assertTrue(open.url.contains("fixture-163"));}assertEquals(replacement.uri,new Library(c).find(copy.uri).uri);}

}
